<?php require_once __DIR__.'/db.php';require_once __DIR__.'/includes/auth.php';requireAdmin();$rows=$conn->query("SELECT COALESCE(s.student_name,u.full_name,'Unknown') person,COALESCE(e.title,'Event removed') event_title,r.registration_status,r.registered_at FROM registrations r LEFT JOIN students s ON s.id=r.student_id LEFT JOIN users u ON u.id=r.user_id LEFT JOIN events e ON e.id=r.event_id ORDER BY r.registered_at DESC")->fetch_all(MYSQLI_ASSOC);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registrations</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="standalone"><a href="dashboard.php">← Dashboard</a><h1>Registrations</h1><section class="panel"><table><thead><tr><th>PERSON</th><th>EVENT</th><th>STATUS</th><th>REGISTERED</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['person'])?></td><td><?=e($r['event_title'])?></td><td><?=e($r['registration_status'])?></td><td><?=e($r['registered_at'])?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>